pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) { ok = ret; } catch { ok = false; }
