pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        // Only the admin (deployer, i.e. this test contract in setUp) may call successfully;
        // non-admin callers revert in both versions, so restrict caller to the admin to stay admissible.
        vm.prank(caller);
        bool ok;
        bool returned;
        try c.setOwner(newOwner) returns (bool s) {
            ok = true;
            returned = s;
        } catch {
            ok = false;
            returned = true; // neutral so the assertion fails on unexpected reverts
        }
        assertTrue(ok && returned && c.owner() == newOwner);
    }
}

