import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.prank(caller);
        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool success) {
            ok = true;
            ret = success;
        } catch {
            ok = false;
        }
        // General rule: only the admin may change the owner, and whenever the
        // call succeeds it must report success == true for ANY newOwner.
        // (The buggy version returns owner == _owner, which is not the
        // unconditional true the reference guarantees, so some input breaks it.)
        assertTrue(!ok || ret, "setOwner must return true whenever it completes");
    }
}

