contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // admin is the deployer of c, i.e. this test contract; owner starts as deployer too.
        // Domain kept WIDE: any address for newOwner is admissible (no constraints).
        vm.prank(address(this));
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.setOwner.selector, newOwner)
        );
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (bool)) == true && c.owner() == newOwner,
            "a completed admin setOwner must return true and set owner to the requested address");
    }
}

