pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // only the admin (the deploying contract) can pass the modifier;
        // keep the caller admissible by pranking the deployer for non-admin callers via vm.deal-free prank:
        // admin is address(this), so prank it when caller is admin; otherwise expect revert in both.
        bool ok;
        bool ret = false;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = true;
            ret = success;
        } catch {
            ok = false;
        }
        if (!ok) {
            // reverted: both versions revert identically (onlyAdmin)
            assertTrue(true);
        } else {
            // General rule: any setOwner call that completes returns true
            assertTrue(ret);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { c = new C(); admin = msg.sender; }

    function testFuzz_property(address actor, address newAddr) public {
        vm.assume(actor != admin);
        vm.assume(newAddr != admin && newAddr != actor);
        // admin transfers ownership to actor (allowed for both versions)
        vm.prank(admin);
        c.setOwner(actor);
        // a non-admin (the new owner) tries to transfer ownership again
        vm.prank(actor);
        try c.setOwner(newAddr) {
            // only the admin may ever change owner: it must still be actor
            assertTrue(c.owner() == actor);
        } catch {
            assertTrue(c.owner() == actor);
        }
    }
}
